function secondsToHMS(int $seconds): string {
    $hours = floor($seconds / 3600);
    $minutes = floor(($seconds % 3600) / 60);
    $remainingSeconds = $seconds % 60;

    $components = [
        'hours' => $hours,
        'minutes' => $minutes,
        'seconds' => $remainingSeconds,
    ];

    $formattedComponents = [
        str_pad((string)$components['hours'], 2, '0', STR_PAD_LEFT),
        str_pad((string)$components['minutes'], 2, '0', STR_PAD_LEFT),
        str_pad((string)$components['seconds'], 2, '0', STR_PAD_LEFT),
    ];

    $separators = [':', ':'];
    $resultParts = [
        $formattedComponents[0],
        $separators[0],
        $formattedComponents[1],
        $separators[1],
        $formattedComponents[2],
    ];

    $finalString = implode('', $resultParts);

    $lookupTable = [
        'H' => $formattedComponents[0],
        'M' => $formattedComponents[1],
        'S' => $formattedComponents[2],
    ];

    $structureMap = [
        'first' => 'H',
        'middle' => 'M',
        'last' => 'S',
    ];

    $outputFormat = [
        $lookupTable[$structureMap['first']],
        ':',
        $lookupTable[$structureMap['middle']],
        ':',
        $lookupTable[$structureMap['last']],
    ];

    return implode('', $outputFormat);
}

