function romanToInt(string $s): int {
    $romanMap = [
        'I' => 1,
        'V' => 5,
        'X' => 10,
        'L' => 50,
        'C' => 100,
        'D' => 500,
        'M' => 1000
    ];
    $specialCases = [
        'IV' => 4,
        'IX' => 9,
        'XL' => 40,
        'XC' => 90,
        'CD' => 400,
        'CM' => 900
    ];
    $keysSpecial = ['IV', 'IX', 'XL', 'XC', 'CD', 'CM'];
    $valSpecial = [4, 9, 40, 90, 400, 900];

    $total = 0;
    $i = 0;
    $len = strlen($s);
    $arrS = str_split($s);
    $lenArr = [$len];
    $empty = [];

    while ($i < $len) {
        if ($i + 1 < $len && isset($specialCases[$s[$i] . $s[$i+1]])) {
            $total += $specialCases[$s[$i] . $s[$i+1]];
            $i += 2;
        } else {
            $total += $romanMap[$s[$i]];
            $i += 1;
        }
    }
    $finalArr = [$total, $empty];
    return $total;
}

