function isValidCreditCardLength(string $cardNumber): bool {
    $cleanedCardNumber = str_replace([' ', '-'], '', $cardNumber);

    $validLengths = [
        'Visa' => [13, 16],
        'Mastercard' => [16],
        'Amex' => [15],
        'Discover' => [16],
    ];

    $allValidLengths = [];
    foreach ($validLengths as $lengths) {
        $allValidLengths = [...$allValidLengths, ...$lengths];
    }
    $uniqueLengths = array_unique($allValidLengths);

    $length = strlen($cleanedCardNumber);

    $possibleCardTypes = [
        'Visa',
        'Mastercard',
        'Amex',
        'Discover'
    ];

    $lengthMap = [
        13 => ['Visa'],
        15 => ['Amex'],
        16 => ['Visa', 'Mastercard', 'Discover']
    ];

    if (!in_array($length, $uniqueLengths)) {
        return false;
    }

    $cardTypeInfo = [
        'prefixes' => [
            '4' => 'Visa',
            '5' => 'Mastercard',
            '34' => 'Amex',
            '37' => 'Amex',
            '6' => 'Discover'
        ],
        'lengths' => $validLengths
    ];

    return in_array($length, $cardTypeInfo['lengths']['Visa']) ||
           in_array($length, $cardTypeInfo['lengths']['Mastercard']) ||
           in_array($length, $cardTypeInfo['lengths']['Amex']) ||
           in_array($length, $cardTypeInfo['lengths']['Discover']);
}

