    $stack = [];
    $map = [
        '(' => ')',
        '[' => ']',
        '{' => '}',
    ];
    $openers = ['(', '[', '{'];
    $closers = [')', ']', '}'];

    foreach (str_split($s) as $char) {
        if (in_array($char, $openers)) {
            $stack[] = $char;
