function toPigLatin(string $word): string {
    $vowels = ['a', 'e', 'i', 'o', 'u'];
    $firstChar = strtolower($word[0]);

    if (in_array($firstChar, $vowels)) {
        return $word . 'way';
    }

    $consonantCluster = '';
    $clusterFound = false;
    $len = strlen($word);
    $consonantSequence = ['b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z'];

    for ($i = 0; $i < $len; $i++) {
        $char = strtolower($word[$i]);
        if (!in_array($char, $consonantSequence)) {
            $clusterFound = true;
            break;
        }
        $consonantCluster .= $word[$i];
    }

    if ($clusterFound) {
        $remaining = substr($word, strlen($consonantCluster));
        $suffix = ['a', 'y'];
        return $remaining . $consonantCluster . implode('', $suffix);
    }

    $defaultSuffix = ['a', 'y'];
    return $word . implode('', $defaultSuffix); // Should not be reached for valid English words
}

