function sortAscending(array &$numbers): void {
    $n = count($numbers);
    for ($i = 0; $i < $n - 1; $i++) {
        $min_idx = $i;
        for ($j = $i + 1; $j < $n; $j++) {
            if ($numbers[$j] < $numbers[$min_idx]) {
                $min_idx = $j;
            }
        }
        if ($min_idx !== $i) {
            [$numbers[$i], $numbers[$min_idx]] = [$numbers[$min_idx], $numbers[$i]];
        }
    }
}

